'use strict';
const uiPaths={map:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 16v-3m4 3V7m4 9v-6"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5m-15-9 3 2 5-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',star:'<path d="m12 3 2.9 5.8 6.4.9-4.6 4.5 1.1 6.4L12 17.5l-5.8 3.1 1.1-6.4-4.6-4.5 6.4-.9z"/>',pin:'<path d="M19.5 10c0 6-7.5 11-7.5 11S4.5 16 4.5 10a7.5 7.5 0 0 1 15 0z"/><circle cx="12" cy="10" r="2.5"/>',swap:'<path d="M5 7h14l-4-4M19 17H5l4 4M19 7l-4 4M5 17l4-4"/>',walk:'<circle cx="13" cy="4" r="2"/><path d="m9 10 3-3 4 4 4 1M12 8l-2 7-4 6m4-6 5 1 2 5M5 13l3-3"/>',car:'<path d="m5 9 2-5h10l2 5M4 17V9h16v8M4 14h16M6 17v3m12-3v3M7 11h1m8 0h1"/>',arrow:'<path d="m3 10 18-7-7 18-3-8zM11 13l10-10"/>',chevron:'<path d="m9 5 7 7-7 7"/>',locate:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',layers:'<path d="m3 8 9-5 9 5-9 5zM3 12l9 5 9-5M3 16l9 5 9-5"/>'};
function ui(type){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${uiPaths[type]||uiPaths.pin}</svg>`}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=ui(el.dataset.icon));
let floor=1,toastTimer=null,favorites=[];
try{const saved=JSON.parse(localStorage.getItem('campus-favorites-v1')||'[]');favorites=Array.isArray(saved)?saved.filter(id=>buildings.some(b=>b.id===id)):[]}catch{}
const places=[{name:'体育馆',pos:[-316,-305,0]},{name:'多功能厅',pos:[-201,-371,0]},{name:'行政中心',pos:[43,-67,0]},{name:'学生中心',pos:[-73,83,0]},{name:'运动场',pos:[-403,186,0]},{name:'球场',pos:[-408,-31,0]},{name:'北门',pos:[0,-367,0]},{name:'南门',pos:[17,376,0]}];
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
function letter(b){return `<span class="letter" style="--theme:${b.color}">${b.id}</span>`}
function updateRoute(){const from=$('#origin').value,to=$('#destination').value;if(from===to&&from){$('#routeHeadline').textContent='起点与目的地相同';$('#routeDescription').textContent='可以选择另一栋楼，或查看当前楼栋。';$('#routeAction').innerHTML=ui('pin')+'查看楼栋'}else if(from){$('#routeHeadline').textContent=`${from} 楼 → ${to} 楼`;$('#routeDescription').textContent='实地路线待核验，距离与预计时间暂缺。';$('#routeAction').innerHTML=ui('arrow')+'查看路线准备情况'}else{$('#routeHeadline').textContent='先认识校园，再出发';$('#routeDescription').textContent='选择楼栋，查看专业与空间信息。';$('#routeAction').innerHTML=ui('arrow')+'查看楼栋'}}
function renderBuildings(){$('#buildings').innerHTML=buildings.map(b=>`<button class="building-row ${selected===b.id?'active':''}" data-building="${b.id}" aria-label="选择 ${b.id} 楼 ${b.full}" aria-pressed="${selected===b.id}">${letter(b)}<span>${b.id==='C'?'创新创业':b.id==='F'?'室内地图试点':b.full}</span>${ui('chevron')}</button>`).join('')}
function choose(id,show=true){const b=buildings.find(b=>b.id===id);if(!b)return;selected=id;$('#destination').value=id;renderBuildings();updateRoute();const panel=$('#buildingInfo');panel.style.setProperty('--theme',b.color);panel.style.setProperty('--soft',b.soft);panel.innerHTML=`<div class="popover-top">${letter(b)}<span><b>${b.full}</b><small>BUILDING ${b.id} · ${floor}F 预览</small></span><button id="closeInfo" aria-label="关闭楼栋信息">×</button></div><p>${b.desc}</p><div class="theme-story">${icon(b.symbol)}<span>${b.tags.join(' / ')}<small>专业主题 · 创意视觉标识</small></span></div>${['B','F','G'].includes(id)?`<a class="f-indoor-action" href="indoor.html?building=${id}">进入 ${id} 栋室内地图 ↗</a>`:''}<div class="popover-actions"><button id="setOrigin">设为起点</button><button id="favorite">${favorites.includes(id)?'已收藏 ★':'收藏地点 ☆'}</button></div>`;panel.hidden=!show;if(show&&window.innerWidth<=760)canvas.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#closeInfo').onclick=()=>panel.hidden=true;$('#setOrigin').onclick=()=>{$('#origin').value=id;updateRoute();toast(`已将 ${id} 楼设为起点，请选择目的地。`)};$('#favorite').onclick=()=>{if(favorites.includes(id))favorites=favorites.filter(x=>x!==id);else favorites.push(id);try{localStorage.setItem('campus-favorites-v1',JSON.stringify(favorites))}catch{toast('浏览器无法保存收藏，本次访问中仍可使用。')}$('#favorite').textContent=favorites.includes(id)?'已收藏 ★':'收藏地点 ☆'};makeModel();dirty=true}
for(const b of buildings){const label=`${b.id}  ${b.id==='F'?'室内地图试点':b.full}`;$('#origin').add(new Option(label,b.id));$('#destination').add(new Option(label,b.id))}$('#destination').value='D';$('#origin').onchange=updateRoute;$('#destination').onchange=e=>choose(e.target.value);$('#swap').onclick=()=>{const from=$('#origin').value;if(!from){toast('请先选择一个起点，再交换起终点。');return}$('#origin').value=$('#destination').value;choose(from,false);updateRoute()};$('#buildings').onclick=e=>{const b=e.target.closest('[data-building]');if(b)choose(b.dataset.building)};
$('#collapseBuildings').onclick=()=>{const list=$('#buildings');list.hidden=!list.hidden;$('#collapseBuildings').textContent=list.hidden?'展开':'收起';$('#collapseBuildings').setAttribute('aria-expanded',String(!list.hidden))};
function setNav(page){document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page))}
function dialog(title,body,eyebrow='XJTLU TAICANG · CAMPUS ATLAS'){$('#dialogContent').innerHTML=`<span class="dialog-eyebrow">${eyebrow}</span><h2 class="dialog-title">${title}</h2>${body}`;$('#contentDialog').showModal()}
$('.dialog-close').onclick=()=>$('#contentDialog').close();$('#contentDialog').addEventListener('close',()=>setNav('map'));
function routeDialog(){dialog('走得准，需要真实的通行数据。','<p class="dialog-text">起点和目的地已经可以选择。实际导航将在核对楼层平面图、出入口、楼梯、电梯和跨楼连廊之后开放。</p><div class="note-box">当前尚未建立可通行路线网络，因此本版不显示距离、预计到达时间或实时定位。画面中的道路和桥梁是空间示意，不能作为通行依据。</div><p class="dialog-text">下一步：先完成一栋楼的教室定位与实地验证，再逐步扩展到跨楼导航。</p>','WAYFINDING · DATA IN PROGRESS')}
$('#routeAction').onclick=()=>{if($('#origin').value&&$('#origin').value!==$('#destination').value)routeDialog();else choose($('#destination').value)};$('#walk').onclick=()=>toast('步行是计划支持的首个导航方式，路线数据正在完善。');$('#drive').onclick=()=>toast('驾车导航暂未开放，目前优先完善步行找教室。');
function search(){const raw=$('#buildingSearch').value.trim(),q=raw.toLowerCase(),id=q.replace(/[栋楼\s]/g,'').toUpperCase(),list=$('#searchResults');$('#clearSearch').hidden=!raw;list.hidden=false;const matches=buildings.filter(b=>!q||b.id===id||(b.name+b.full+b.tags.join('')).toLowerCase().includes(q));const pm=q?places.filter(p=>p.name.includes(q)):[];list.innerHTML=matches.map(b=>`<button class="search-result" data-result="${b.id}">${letter(b)}<span>${b.full}<small>${b.id} 楼 · 专业与楼栋位置</small></span></button>`).join('')+pm.map(p=>`<button class="search-result" data-place="${p.name}">${ui('pin')}<span>${p.name}<small>参考图标注 · 位置待核验</small></span></button>`).join('')+(matches.length||pm.length?'':'<p>暂未找到对应地点。可以搜索 A–G 楼、机器人、创业或艺术。具体教室门牌正在录入。</p>')+`<a class="search-result f-search-link" href="indoor.html?building=F&q=${encodeURIComponent(raw)}">B / F / G 室内地图 · 搜索房间 ↗</a><p>B 栋 1–5F、F / G 栋 BF–5F 已有地图；其余楼栋资料待补充。</p>`}
$('#searchForm').onsubmit=e=>{e.preventDefault();search()};$('#buildingSearch').oninput=search;$('#buildingSearch').onfocus=search;$('#clearSearch').onclick=()=>{$('#buildingSearch').value='';$('#clearSearch').hidden=true;$('#searchResults').hidden=true};$('#buildingSearch').onkeydown=e=>{if(e.key==='Escape')$('#searchResults').hidden=true};
$('#searchResults').onclick=e=>{const b=e.target.closest('[data-result]'),el=e.target.closest('[data-place]');if(b){choose(b.dataset.result);$('#buildingSearch').value=b.dataset.result+' 楼';$('#searchResults').hidden=true}else if(el){const place=places.find(p=>p.name===el.dataset.place);panX=panY=0;const q=project(place.pos);panX=centerX-q[0];panY=centerY-q[1];dirty=true;$('#buildingSearch').value=place.name;$('#searchResults').hidden=true;toast(`${place.name} · 参考图标注，实际位置待核验。`)}};document.addEventListener('pointerdown',e=>{if(!e.target.closest('.search-area'))$('#searchResults').hidden=true});
$('#floors').onclick=e=>{const b=e.target.closest('[data-floor]');if(!b)return;floor=Number(b.dataset.floor);if(['B','F','G'].includes(selected)){location.href='indoor.html?building='+selected+'&floor='+floor+'F';return}document.querySelectorAll('[data-floor]').forEach(el=>el.classList.toggle('active',el===b));if(!$('#buildingInfo').hidden)choose(selected);dialog(`${selected} 楼 · ${floor}F 平面图待录入`,`<p class="dialog-text">这里将展示这一层的教室、走廊、楼梯和电梯。收到清晰的楼层展示牌并完成核对后，就可以替换为真实平面图。</p><div class="floor-schematic"><span>教室</span><span>走廊</span><span>楼梯 / 电梯</span></div><div class="note-box">1F–5F 是本次界面预览的占位选项，不代表已核实的实际楼层数量；上方方框也不代表真实布局。</div>`,'FLOOR PLAN · A PLACE FOR REAL DATA')};
$('#layersBtn').onclick=()=>{$('#layerPanel').hidden=!$('#layerPanel').hidden;$('#layersBtn').setAttribute('aria-expanded',String(!$('#layerPanel').hidden))};$('#labels').onchange=e=>{showLabels=e.target.checked;dirty=true};$('#trees').onchange=e=>{showTrees=e.target.checked;makeModel();dirty=true};$('#themes').onchange=e=>{showThemes=e.target.checked;dirty=true};
function guide(){setNav('guide');dialog('从一栋楼，认识一座校园。','<p class="dialog-text">校园以相互连接的环形建筑为主要空间线索。先找到楼栋，再逐步定位楼层和教室。</p><div class="guide-grid"><div class="guide-item"><span>STUDY & CREATE</span><h3>A–G 楼</h3><p>制造、学者空间、创业、AI、供应链与艺术科技；F 楼已录入楼层资料，专业定位待补充。</p></div><div class="guide-item"><span>SPORTS & LIFE</span><h3>体育馆与运动场</h3><p>参考图中的校园体育空间，开放时间与入口信息待收集。</p></div><div class="guide-item"><span>CAMPUS SERVICES</span><h3>行政中心与学生中心</h3><p>名称与大致位置参考本次提供的效果图，待用官方资料核验。</p></div><div class="guide-item"><span>CONNECTED CAMPUS</span><h3>环廊与出入口</h3><p>各栋楼相互连接，具体可通行楼层与连廊关系仍需实地确认。</p></div></div><p class="dialog-text">地图中的树木、绿地和建筑细节用于展示整体风格，尚未达到测绘精度。</p>','EXPLORE YOUR CAMPUS')}
function showFavorites(){setNav('favorites');dialog('把常去的地方，放在手边。',favorites.length?favorites.map(id=>{const b=buildings.find(b=>b.id===id);return `<div class="favorite-row">${letter(b)}<button data-open-favorite="${id}">${b.full}</button><button data-remove-favorite="${id}">移除</button></div>`}).join('')+'<p class="dialog-text">收藏保存在当前浏览器中。</p>':`<div class="empty-state">${ui('star')}<p>还没有收藏地点。<br>点开任意楼栋，在介绍卡片里点击“收藏地点”。</p></div>`,'SAVED PLACES')}
$('#dialogContent').onclick=e=>{const open=e.target.closest('[data-open-favorite]'),remove=e.target.closest('[data-remove-favorite]');if(open){$('#contentDialog').close();choose(open.dataset.openFavorite)}if(remove){favorites=favorites.filter(id=>id!==remove.dataset.removeFavorite);try{localStorage.setItem('campus-favorites-v1',JSON.stringify(favorites))}catch{}$('#contentDialog').close();showFavorites()}};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const page=b.dataset.page;setNav(page);if(page==='map'){$('#reset').click();$('#buildingInfo').hidden=true}else if(page==='search'){$('#buildingSearch').focus();search();toast('F 栋房间查询已开放，点击搜索结果中的室内地图入口。')}else if(page==='guide')guide();else if(page==='favorites')showFavorites();else if(page==='schedule')dialog('下一节课，一眼就知道。','<p class="dialog-text">后续计划支持导入课表，集中查看每天的上课时间、课程名称和教室，并从课程卡片直接进入校园地图。</p><div class="note-box">课表导入暂未开放。下一阶段将先完成教室编号与楼栋、楼层的准确对应，再接入课程数据。</div>','YOUR TIMETABLE · COMING NEXT')});$('#guideCard').onclick=guide;
$('#contributeBtn').onclick=()=>dialog('一起把校园，走明白。','<p class="dialog-text">从你熟悉的一层楼开始，就能帮助下一位同学少走一段弯路。</p><div class="note-box">需要收集：清晰的楼层展示牌、教室门牌、楼梯与电梯位置、入口实拍、跨楼连廊所在楼层，以及实际通行限制。</div><p class="dialog-text">请将资料交给项目发起人。本版暂不提供在线上传功能。</p>','BUILD IT TOGETHER');
$('#referenceBtn').onclick=()=>dialog('参考资料与数据说明','<p class="dialog-text">界面按你最新提供的蓝白色地图参考设计。楼栋专业按你确认的内容填写，D 楼为人工智能与大数据，B 楼为学者空间。</p><div class="reference-grid"><figure><img src="reference/campus-map.jpg" alt="用户提供的校园地图"><figcaption>校园地图 · 相对位置参考</figcaption></figure><figure><img src="reference/aerial.jpg" alt="用户提供的校园航拍图"><figcaption>航拍照片 · 建筑形态参考</figcaption></figure></div><div class="note-box">当前是可交互的设计原型，建筑尺寸、楼层数量、河岸形状、入口方位与通行关系尚未实测。未接入实时定位或付费地图 API，不提供实际路线与时间估算。</div><p class="dialog-text">模型中的行政中心、学生中心、体育馆、多功能厅等设施名称参考本次效果图，后续需要官方图示或实地资料确认。</p>','REFERENCE & VERIFICATION');
